<script setup lang="ts">
import { onMounted,ref } from 'vue'; import { Ban,Check,FileCheck,Printer,RotateCcw,Send,XCircle } from 'lucide-vue-next'; import { useRoute,useRouter } from 'vue-router'; import AppBadge from '@/components/common/AppBadge.vue'; import AppButton from '@/components/common/AppButton.vue'; import AppModal from '@/components/common/AppModal.vue'; import AppBreadcrumb from '@/components/layout/AppBreadcrumb.vue'; import { salesInvoiceService } from '@/services/sales-invoice.service'; import { useAuthStore } from '@/stores/auth.store'; import { useNotificationStore } from '@/stores/notification.store'; import type { SalesInvoice,SalesInvoiceStatus } from '@/types/sales'; import { getApiErrorMessage } from '@/utils/error'
const id=Number(useRoute().params.id),router=useRouter(),auth=useAuthStore(),notifications=useNotificationStore();const invoice=ref<SalesInvoice|null>(null),loading=ref(true),busy=ref(false),error=ref(''),modal=ref<'reject'|'cancel'|'reverse'|null>(null),reason=ref(''),reverseDate=ref(new Date().toISOString().slice(0,10));const labels:Record<SalesInvoiceStatus,string>={draft:'Draft',pending_approval:'Menunggu Persetujuan',approved:'Disetujui',rejected:'Ditolak',posted:'Posted',partially_paid:'Dibayar Sebagian',paid:'Lunas',reversed:'Reversed',cancelled:'Dibatalkan'};const tone=(s:SalesInvoiceStatus):'green'|'amber'|'red'|'blue'|'slate'=>s==='posted'||s==='paid'?'green':s==='approved'?'blue':s==='pending_approval'||s==='partially_paid'?'amber':s==='rejected'||s==='reversed'||s==='cancelled'?'red':'slate';const money=(v:string|number)=>new Intl.NumberFormat('id-ID',{style:'currency',currency:invoice.value?.currency??'IDR',maximumFractionDigits:2}).format(Number(v));const date=(v:string)=>new Intl.DateTimeFormat('id-ID',{dateStyle:'medium'}).format(new Date(`${v.slice(0,10)}T00:00:00`))
const load=async()=>{loading.value=true;error.value='';try{invoice.value=await salesInvoiceService.get(id)}catch(e){error.value=getApiErrorMessage(e,'Sales invoice gagal dimuat.')}finally{loading.value=false}};const run=async(action:()=>Promise<unknown>,message:string)=>{busy.value=true;try{await action();notifications.push(message);modal.value=null;reason.value='';await load()}catch(e){notifications.push(getApiErrorMessage(e,'Tindakan gagal diproses.'),'error')}finally{busy.value=false}};const reasonAction=()=>{if(reason.value.trim().length<3)return notifications.push('Alasan minimal 3 karakter.','error');if(modal.value==='reject')return run(()=>salesInvoiceService.reject(id,reason.value),'Sales invoice ditolak.');if(modal.value==='cancel')return run(()=>salesInvoiceService.cancel(id,reason.value),'Sales invoice dibatalkan.');return run(()=>salesInvoiceService.reverse(id,reverseDate.value,reason.value),'Sales invoice berhasil direversal.')};const print=()=>window.print();onMounted(load)
</script>
<template><div><AppBreadcrumb/><p v-if="error" class="mb-4 rounded bg-red-50 p-3 text-sm text-red-700">{{error}}</p><div v-if="loading" class="panel space-y-3 p-5"><div v-for="i in 7" :key="i" class="h-9 animate-pulse rounded bg-slate-100"/></div><template v-else-if="invoice"><header class="mb-6 flex flex-wrap items-start justify-between gap-4 print:hidden"><div><h1 class="text-2xl font-bold">{{invoice.invoice_number}}</h1><p class="text-sm text-slate-500">{{invoice.customer_name}} · jatuh tempo {{date(invoice.due_date)}}</p></div><div class="flex flex-wrap gap-2"><AppButton v-if="auth.hasPermission('sales-invoices.print')" variant="secondary" :icon="Printer" @click="print">Cetak</AppButton><AppButton v-if="['draft','rejected'].includes(invoice.status)&&!invoice.sales_order_id&&auth.hasPermission('sales-invoices.update')" variant="secondary" @click="router.push(`/sales/invoices/${id}/edit`)">Edit</AppButton><AppButton v-if="['draft','rejected'].includes(invoice.status)&&auth.hasPermission('sales-invoices.submit')" :icon="Send" :loading="busy" @click="run(()=>salesInvoiceService.submit(id),'Sales invoice diajukan.')">Ajukan</AppButton><AppButton v-if="invoice.status==='pending_approval'&&auth.hasPermission('sales-invoices.approve')" :icon="Check" :loading="busy" @click="run(()=>salesInvoiceService.approve(id),'Sales invoice disetujui.')">Setujui</AppButton><AppButton v-if="invoice.status==='pending_approval'&&auth.hasPermission('sales-invoices.reject')" variant="danger" :icon="XCircle" @click="modal='reject'">Tolak</AppButton><AppButton v-if="invoice.status==='approved'&&auth.hasPermission('sales-invoices.post')" :icon="FileCheck" :loading="busy" @click="run(()=>salesInvoiceService.post(id),'Sales invoice berhasil diposting.')">Posting</AppButton><AppButton v-if="['draft','rejected'].includes(invoice.status)&&auth.hasPermission('sales-invoices.cancel')" variant="danger" :icon="Ban" @click="modal='cancel'">Batalkan</AppButton><AppButton v-if="invoice.status==='posted'&&Number(invoice.paid_amount)===0&&auth.hasPermission('sales-invoices.reverse')" variant="danger" :icon="RotateCcw" @click="modal='reverse'">Reverse</AppButton></div></header><section class="panel mb-5 p-5"><div class="mb-5 flex justify-between"><div><h2 class="text-lg font-semibold">{{invoice.invoice_number}}</h2><p class="text-sm text-slate-500">{{date(invoice.invoice_date)}}</p></div><AppBadge :tone="tone(invoice.status)">{{labels[invoice.status]}}</AppBadge></div><dl class="grid gap-4 text-sm sm:grid-cols-2 lg:grid-cols-4"><div><dt class="text-slate-500">Pelanggan</dt><dd class="font-semibold">{{invoice.customer_code}} · {{invoice.customer_name}}</dd></div><div><dt class="text-slate-500">Gudang</dt><dd>{{invoice.warehouse_code?`${invoice.warehouse_code} · ${invoice.warehouse_name}`:'-'}}</dd></div><div><dt class="text-slate-500">Referensi</dt><dd>{{invoice.reference||'-'}}</dd></div><div><dt class="text-slate-500">Mata Uang/Kurs</dt><dd>{{invoice.currency}} · {{invoice.exchange_rate}}</dd></div><div><dt class="text-slate-500">Status Pembayaran</dt><dd class="capitalize">{{invoice.payment_status.replaceAll('_',' ')}}</dd></div><div><dt class="text-slate-500">Sudah Dibayar</dt><dd>{{money(invoice.paid_amount)}}</dd></div><div><dt class="text-slate-500">Outstanding</dt><dd class="font-bold text-blue-700">{{money(invoice.outstanding_amount)}}</dd></div><div><dt class="text-slate-500">Jurnal</dt><dd>{{invoice.journal_id?`#${invoice.journal_id}`:'Belum diposting'}}</dd></div></dl><p v-if="invoice.notes" class="mt-4 whitespace-pre-wrap border-t pt-4 text-sm text-slate-600">{{invoice.notes}}</p><p v-if="invoice.rejection_reason" class="mt-4 rounded bg-red-50 p-3 text-sm text-red-700">Alasan penolakan: {{invoice.rejection_reason}}</p><p v-if="invoice.cancellation_reason" class="mt-4 rounded bg-red-50 p-3 text-sm text-red-700">Alasan pembatalan: {{invoice.cancellation_reason}}</p></section><section class="panel overflow-hidden"><div class="overflow-x-auto"><table class="w-full text-left text-sm"><thead class="bg-slate-50"><tr><th class="p-3">Item</th><th class="p-3 text-right">Qty</th><th class="p-3">Satuan</th><th class="p-3 text-right">Harga</th><th class="p-3 text-right">Diskon</th><th class="p-3 text-right">Pajak</th><th class="p-3 text-right">Subtotal</th></tr></thead><tbody class="divide-y"><tr v-for="line in invoice.lines" :key="line.id"><td class="p-3"><b>{{line.item_code}} · {{line.item_name}}</b><small v-if="line.description" class="block text-slate-500">{{line.description}}</small></td><td class="p-3 text-right">{{line.quantity}}</td><td class="p-3">{{line.unit_code}}</td><td class="p-3 text-right">{{money(line.unit_price)}}</td><td class="p-3 text-right">{{money(line.discount)}}</td><td class="p-3 text-right">{{money(line.tax_amount)}}</td><td class="p-3 text-right font-semibold">{{money(line.subtotal)}}</td></tr></tbody></table></div><footer class="flex justify-end border-t bg-slate-50 p-5"><dl class="w-full max-w-sm space-y-2 text-sm"><div class="flex justify-between"><dt>Subtotal</dt><dd>{{money(invoice.subtotal)}}</dd></div><div class="flex justify-between"><dt>Diskon</dt><dd>{{money(invoice.discount)}}</dd></div><div class="flex justify-between"><dt>Pajak</dt><dd>{{money(invoice.tax)}}</dd></div><div class="flex justify-between border-t pt-2 text-lg font-bold"><dt>Total</dt><dd>{{money(invoice.grand_total)}}</dd></div></dl></footer></section></template><AppModal :open="modal!==null" :title="modal==='reject'?'Tolak Sales Invoice':modal==='cancel'?'Batalkan Sales Invoice':'Reverse Sales Invoice'" :close-disabled="busy" @close="modal=null"><label v-if="modal==='reverse'" class="form-label mb-4 block">Tanggal Reversal<input v-model="reverseDate" type="date" class="field mt-1"/></label><label class="form-label">Alasan<textarea v-model="reason" class="field mt-1 min-h-24" maxlength="1000"/></label><template #footer><AppButton variant="secondary" :disabled="busy" @click="modal=null">Kembali</AppButton><AppButton variant="danger" :loading="busy" @click="reasonAction">Proses</AppButton></template></AppModal></div></template>
